# rapids-g sequencer (rapids TASK-034): one gatling core + ROM + scratch + MMIO
# Location: projects/components/dma-ip/rapids/rtl/filelists/macro_g/rapids_seq_g.f

# the firmware image (generated by bin/gen_rapids_g_fw.py)
+incdir+$REPO_ROOT/projects/components/dma-ip/rapids/rtl/macro_g/generated/fw
+incdir+$REPO_ROOT/rtl/amba/includes

# the hart round robin of the register mailbox
-f $REPO_ROOT/rtl/common/filelists/arbiter_round_robin_simple_ack.f

# gatling, unchanged, through its own filelist (it pulls kestrel's fubs)
-f $GATLING_ROOT/rtl/filelists/top/gatling_core.f

$REPO_ROOT/projects/components/dma-ip/rapids/rtl/macro_g/rapids_seq_g.sv
